// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    bool private __entered;

    function setUp() public { c = new SimpleWallet(); }

    // This test contract is c's owner (deployed in setUp) AND the re-entrant callee,
    // since withdraw() sends to msg.sender.
    receive() external payable {
        if (!__entered) {
            __entered = true;
            c.withdraw(__lastAmount); // exactly ONE state-changing re-entry
        }
    }

    uint256 private __lastAmount;

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint256).max / 2);
        __lastAmount = amount;
        __entered = false;
        vm.deal(address(c), amount);

        bool ok;
        try c.withdraw(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a withdraw to a re-entrant receiver ALWAYS reverts the
        // outer call (the nested transfer runs out of gas and bubbles up).
        // The mutant's gas-forwarding call lets the re-entry succeed, so ok == true.
        assertTrue(!ok, "withdraw must revert when the receiver re-enters");
    }
}
